// New FeedPanel: loads on render, plus an inline 'Like' action.
+function FeedPanel({ userId }: { userId: string }) {
+  return (
+    <Suspense fallback={<FeedSkeleton />}>
+      <ActivityFeed userId={userId} />
+    </Suspense>
+  );
+}
+
+function ActivityFeed({ userId }: { userId: string }) {
+  const posts = use(fetchFeed(userId)); // reads on render; rejects on API error
+  async function onLike(id: string) {
+    await api.like(id);                  // can reject (network/4xx)
+  }
+  return (
+    <ul>
+      {posts.map((p) => (
+        <li key={p.id}>
+          {p.text}
+          <button onClick={() => onLike(p.id)}>Like</button>
+        </li>
+      ))}
+    </ul>
+  );
+}
